package com.shoplocker.fssai.util;

import java.io.File;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.Locale;

import com.openhtmltopdf.outputdevice.helper.BaseRendererBuilder;
import com.openhtmltopdf.pdfboxout.PdfRendererBuilder;

/**
 * Shared XHTML building blocks for every certificate the server generates -
 * FSSAI, GST and MSME. One stylesheet, one header, one footer: keeping them
 * here is what makes "the same format" literally true, since a change to
 * {@link #BASE_CSS} or {@link #footer(String)} restyles all certificates at once.
 */
public final class CertificateTemplate {

    private CertificateTemplate() {}

    private static final org.slf4j.Logger log =
            org.slf4j.LoggerFactory.getLogger(CertificateTemplate.class);

    /** Green "verified" tick, embedded so the PDF needs no external asset. */
    static final String CHECKMARK_PNG_B64 = "data:image/png;base64,";

    /** DukaanLocker shop-with-lock mark shown beside the signature line. */
    static final String LOGO_PNG_B64 = "data:image/png;base64,";

    /**
     * The certificate stylesheet. Shared by all generators - see the class javadoc.
     * The frame carries padding but no border: the page itself is the frame.
     */
    static final String BASE_CSS = """
              @page { size: A4 portrait; margin: 8mm 7mm; }
              * { box-sizing: border-box; margin:0; padding:0; }
              body { font-family: 'Times New Roman', 'Liberation Serif', Times, Georgia, serif; font-size:9pt; color:#1a1a1a; line-height:1.3; background:#fff; }

              /* ===== CONTENT WRAPPER (no border - the page itself is the frame) ===== */
              /* The 30mm top pad is deliberate: the reference certificate opens with a
                 wide ceremonial gap before the department name. */
              .frame { padding:30mm 5mm 6mm; }

              /* ===== HEADER ===== */
              .header { text-align:center; padding:11px 8px 7px; border-bottom:1.5px solid #1F4E79; }
              .header-dept { font-size:15pt; font-weight:bold; color:#1F4E79; letter-spacing:1.4px; }
              .header-board { font-size:11pt; color:#1F4E79; letter-spacing:4.5px; margin-top:3px; }

              /* ===== TITLE ===== */
              .title { text-align:center; font-size:15pt; font-weight:bold; color:#1F4E79; text-transform:uppercase; letter-spacing:2.5px; padding:9px 0 8px; border-bottom:1px solid #B9C6D4; }

              /* ===== LICENSE NUMBER ===== */
              .lic-box { text-align:center; padding:8px 0 6px; }
              .lic-label { font-size:8.5pt; color:#41546A; text-transform:uppercase; letter-spacing:2.2px; }
              .lic-value { font-size:17pt; font-weight:bold; color:#1F4E79; letter-spacing:5px; margin-top:3px; }

              /* ===== CONTENT ===== */
              .content { padding: 0 2px; }

              /* ===== SECTION HEADERS ===== */
              .section { background:#1F4E79; color:#fff; font-size:9pt; font-weight:bold; padding:4px 9px; margin-top:7px; letter-spacing:1.2px; text-transform:uppercase; }

              /* ===== TABLES ===== */
              table { width:100%; border-collapse:collapse; margin:0; }
              td { padding:4px 8px; vertical-align:top; border-bottom:1px solid #E4EAF0; font-size:8.5pt; }
              tr:last-child td { border-bottom:none; }

              /* ===== FIELD ROWS ===== */
              .lbl { width:40%; font-weight:normal; color:#5A6B7D; font-size:8pt; text-transform:uppercase; letter-spacing:0.4px; padding-right:8px; vertical-align:middle; }
              .val { color:#12233A; font-weight:bold; font-size:9pt; vertical-align:middle; }

              /* Status */
              .status-badge { display:inline-block; padding:2px 9px; border-radius:3px; font-size:8pt; font-weight:bold; letter-spacing:0.4px; }
              .badge-active { background:#E7F6EC; color:#1B7A3D; border:1px solid #B7E0C4; }
              .badge-inactive { background:#FDECEC; color:#C53030; border:1px solid #F3BEBE; }

              /* ===== CERTIFICATION ===== */
              .cert-box { background:#F5F7FA; border:1px solid #DDE5ED; margin-top:8px; padding:7px 10px; font-size:8pt; color:#41546A; line-height:1.35; }
              .cert-box .heading { font-size:8.5pt; font-weight:bold; color:#1F4E79; margin-bottom:3px; text-transform:uppercase; letter-spacing:1px; }

              /* ===== FOOTER: QR | spacer | logo | rule | signature | tick ===== */
              .footer { margin-top:9px; }
              .footer td { border-bottom:none; padding:0; vertical-align:middle; }
              .f-qr { width:20%; text-align:left; }
              .f-qr .qr { width:32mm; height:32mm; display:block; }
              .f-gap { width:32%; }
              .f-logo { width:11%; text-align:right; padding-right:7px; }
              .f-logo .logo { width:18mm; height:18mm; display:block; }
              .f-div { width:4%; text-align:center; }
              .f-div .divider { width:2px; height:14mm; background:#7C8FA6; margin:0 auto; }
              .f-text { width:26%; padding:1px 0 0 16px; }
              .sign-1 { font-size:8pt; color:#1F4E79; }
              .sign-2 { font-size:10pt; font-weight:bold; color:#1F4E79; margin-top:1px; }
              .sign-date { font-size:8pt; color:#5A6B7D; margin-top:4px; }
              .f-check { width:7%; text-align:right; padding-left:6px; }
              .f-check .check { width:11mm; height:11mm; display:block; }

              .mb-0 { margin-bottom:0; }
              """;

    /**
     * Compact overrides, appended after {@link #BASE_CSS} so they win on equal
     * specificity. Only applied when a normal render spilled onto a second page.
     */
    static final String COMPACT_CSS = """
              /* ---- compact overrides: same design, denser ---- */
              .frame { padding:14mm 5mm 5mm; }
              .header { padding:8px 8px 5px; }
              .header-dept { font-size:13pt; letter-spacing:1.1px; }
              .header-board { font-size:10pt; letter-spacing:4px; margin-top:2px; }
              .title { font-size:13pt; padding:6px 0 5px; letter-spacing:2px; }
              .lic-box { padding:5px 0 4px; }
              .lic-label { font-size:8pt; letter-spacing:2px; }
              .lic-value { font-size:15pt; letter-spacing:4px; }
              .section { padding:3px 8px; margin-top:5px; font-size:8.5pt; }
              td { padding:3px 7px; font-size:8pt; }
              .lbl { font-size:7.5pt; padding-right:6px; }
              .val { font-size:8.5pt; }
              .status-badge { padding:1px 8px; font-size:7.5pt; }
              .cert-box { margin-top:6px; padding:5px 8px; font-size:7.5pt; }
              .cert-box .heading { font-size:8pt; margin-bottom:2px; }
              .footer { margin-top:6px; }
              """;

    /** Timestamp printed in the signature block, e.g. {@code 08 October 2026, 04:05 PM}. */
    public static String printDate() {
        return new SimpleDateFormat("dd MMMM yyyy, hh:mm a", Locale.ENGLISH).format(new Date());
    }

    /**
     * Wraps the composed body in the XHTML shell, stylesheet and page frame.
     *
     * @param bodyHtml header + title + content + footer markup
     * @param compact  whether to append the compact overrides (single-page fallback)
     */
    public static String document(String bodyHtml, boolean compact) {
        return "<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Strict//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd\">\n" +
                "<html xmlns=\"http://www.w3.org/1999/xhtml\"><head><meta http-equiv=\"Content-Type\" content=\"text/html; charset=UTF-8\"/>\n" +
                "<style>\n" +
                BASE_CSS +
                (compact ? COMPACT_CSS : "") +
                "</style></head><body>\n" +
                "<div class=\"frame\">\n" +
                bodyHtml +
                "</div>\n" +
                "</body></html>";
    }

    /** Two-line authority header: the big line and the acronym below it. */
    public static String header(String authority, String acronym) {
        return "<div class=\"header\">\n" +
                "  <p class=\"header-dept\">" + escapeXml(authority) + "</p>\n" +
                "  <p class=\"header-board\">" + escapeXml(acronym) + "</p>\n" +
                "</div>\n" +
                "\n";
    }

    public static String title(String text) {
        return "<div class=\"title\">" + escapeXml(text) + "</div>\n" +
                "\n";
    }

    /** Centred registration-number block (licence number / GSTIN / Udyam number). */
    public static String idBlock(String label, String value) {
        return "<div class=\"lic-box\">\n" +
                "  <div class=\"lic-label\">" + escapeXml(label) + "</div>\n" +
                "  <div class=\"lic-value\">" + escapeXml(orDash(value)) + "</div>\n" +
                "</div>\n" +
                "\n";
    }

    public static String contentStart() {
        return "<div class=\"content\">\n";
    }

    public static String contentEnd() {
        return "</div>\n" +
                "\n";
    }

    /** Navy section bar. */
    public static String section(String text) {
        return "  <div class=\"section\">" + escapeXml(text) + "</div>\n";
    }

    /** Standard label/value row; the value is escaped. */
    public static String row(String label, String value) {
        return rowHtml(label, escapeXml(orDash(value)));
    }

    /** Label/value row for values that are already HTML (badges, marks). */
    public static String rowHtml(String label, String valueHtml) {
        return "    <tr><td class=\"lbl\">" + escapeXml(label) + "</td><td class=\"val\">" + valueHtml + "</td></tr>\n";
    }

    /** Green / red status pill used by the Status row. */
    public static String badge(String status, boolean active) {
        String text = escapeXml(orDash(status)).toUpperCase(Locale.ENGLISH);
        return "<span class=\"status-badge " + (active ? "badge-active" : "badge-inactive") + "\">" + text + "</span>";
    }

    public static String table(CharSequence rows) {
        return "  <table>\n" + rows + "  </table>\n" +
                "\n";
    }

    /** Section bar + table in one call, the most common body building block. */
    public static String sectionTable(String sectionText, CharSequence rows) {
        return section(sectionText) + table(rows);
    }

    /** The grey certification box; {@code paragraphsHtml} is one or more &lt;p&gt; blocks. */
    public static String certBox(String paragraphsHtml) {
        return "  <div class=\"cert-box\">\n" +
                "    <div class=\"heading\">Certification</div>\n" +
                paragraphsHtml +
                "  </div>\n";
    }

    public static String certParagraph(String text) {
        return "    <p>" + escapeXml(text) + "</p>\n";
    }

    public static String certNote(String text) {
        return "    <p class=\"mb-0\" style=\"margin-top:6px;\"><strong>Note:</strong> " + escapeXml(text) + "</p>\n";
    }

    /**
     * Footer: QR code (left) and the DukaanLocker signature block (right) split by
     * the short vertical rule. The QR encodes {@code qrPayload} verbatim, e.g.
     * {@code FSSAI:21221160000115} / {@code GSTIN:...} / {@code UDYAM:...}.
     */
    public static String footer(String qrPayload) {
        return "<table class=\"footer\">\n" +
                "  <tr>\n" +
                "    <td class=\"f-qr\">" + qrImage(qrPayload) + "</td>\n" +
                "    <td class=\"f-gap\"></td>\n" +
                "    <td class=\"f-logo\"><img class=\"logo\" src=\"" + LOGO_PNG_B64 + "\" alt=\"DukaanLocker\" /></td>\n" +
                "    <td class=\"f-div\"><div class=\"divider\"></div></td>\n" +
                "    <td class=\"f-text\">\n" +
                "      <div class=\"sign-1\">Digitally signed and verified by</div>\n" +
                "      <div class=\"sign-2\">DukaanLocker</div>\n" +
                "      <div class=\"sign-date\">Date: " + printDate() + " IST</div>\n" +
                "    </td>\n" +
                "    <td class=\"f-check\"><img class=\"check\" src=\"" + CHECKMARK_PNG_B64 + "\" alt=\"Verified\" /></td>\n" +
                "  </tr>\n" +
                "</table>\n" +
                "\n";
    }

    /**
     * QR code for the footer. A missing payload or an encoding failure drops the
     * image rather than failing the certificate - the PDF is the deliverable.
     */
    static String qrImage(String qrPayload) {
        if (qrPayload == null || qrPayload.trim().isEmpty()) {
            return "";
        }
        try {
            return "<img class=\"qr\" src=\"" + QrCodePng.pngDataUri(qrPayload.trim())
                    + "\" alt=\"QR\" />";
        } catch (Exception e) {
            log.warn("Could not render the footer QR code for {}", qrPayload, e);
            return "";
        }
    }

    public static String orDash(String text) {
        return (text == null || text.trim().isEmpty()) ? "-" : text;
    }

    /** Escapes special XML characters for safe HTML embedding. */
    public static String escapeXml(String text) {
        if (text == null) return "";
        return text
                .replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("\"", "&quot;")
                .replace("'", "&apos;");
    }

    /**
     * Registers the serif/sans faces the certificate CSS asks for. Windows boxes
     * have Times New Roman, the Docker runtime gets Liberation Serif (metric
     * compatible, fonts-liberation in the Dockerfile) - all under the same family
     * name so the CSS resolves identically everywhere. Regular and bold are
     * registered separately so headings and values keep their weight. Every
     * certificate renderer (FSSAI, GST, MSME) must call this.
     */
    public static void registerFonts(PdfRendererBuilder builder) {
        try {
            registerFont(builder, "Times New Roman", 400,
                    "C:/Windows/Fonts/times.ttf",
                    "/usr/share/fonts/truetype/liberation/LiberationSerif-Regular.ttf",
                    "/usr/share/fonts/truetype/dejavu/DejaVuSerif.ttf",
                    "/Library/Fonts/Times New Roman.ttf");
            registerFont(builder, "Times New Roman", 700,
                    "C:/Windows/Fonts/timesbd.ttf",
                    "/usr/share/fonts/truetype/liberation/LiberationSerif-Bold.ttf",
                    "/usr/share/fonts/truetype/dejavu/DejaVuSerif-Bold.ttf");
            registerFont(builder, "Arial", 400,
                    "C:/Windows/Fonts/arial.ttf",
                    "/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf",
                    "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
                    "/usr/share/fonts/TTF/DejaVuSans.ttf",
                    "/System/Library/Fonts/Helvetica.ttc");
            registerFont(builder, "Arial", 700,
                    "C:/Windows/Fonts/arialbd.ttf",
                    "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf",
                    "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf");
        } catch (Exception e) {
            log.warn("Could not load system fonts for the certificate PDF, may use default font", e);
        }
    }

    /**
     * Registers the first font file that exists on this host under {@code family}
     * at {@code weight}. Candidates are listed per platform (Windows dev box first,
     * then the Debian/Ubuntu runtime image) so the same CSS produces the same face
     * everywhere. A miss is not an error - the renderer falls back to whatever else
     * is registered.
     */
    private static void registerFont(PdfRendererBuilder builder, String family, int weight, String... candidates) {
        for (String path : candidates) {
            File fontFile = new File(path);
            if (fontFile.exists()) {
                builder.useFont(fontFile, family, weight,
                        BaseRendererBuilder.FontStyle.NORMAL, true);
                log.debug("Registered font {} weight {} from {}", family, weight, path);
                return;
            }
        }
        log.debug("No font file found for family '{}' weight {}", family, weight);
    }
}
